import{_ as e,o as a,c as s,aj as t}from"./chunks/framework.C6uXqnaX.js";const u=JSON.parse('{"title":"Skipping component subtrees","description":"","frontmatter":{"untranslated":true},"headers":[],"relativePath":"best-practices/skipping-subtrees.md","filePath":"best-practices/skipping-subtrees.md"}'),o={name:"best-practices/skipping-subtrees.md"};function p(c,n,i,l,d,h){return a(),s("div",null,n[0]||(n[0]=[t(`<h1 id="skipping-component-subtrees" tabindex="-1">Skipping component subtrees <a class="header-anchor" href="#skipping-component-subtrees" aria-label="Permalink to &quot;Skipping component subtrees&quot;">​</a></h1><p>JavaScript, by default, uses mutable data structures that you can reference from multiple different components. Angular runs change detection over your entire component tree to make sure that the most up-to-date state of your data structures is reflected in the DOM.</p><p>Change detection is sufficiently fast for most applications. However, when an application has an especially large component tree, running change detection across the whole application can cause performance issues. You can address this by configuring change detection to only run on a subset of the component tree.</p><h2 id="using-onpush" tabindex="-1">Using <code>OnPush</code> <a class="header-anchor" href="#using-onpush" aria-label="Permalink to &quot;Using \`OnPush\`&quot;">​</a></h2><p>OnPush is the default change detection strategy in Angular (since v22). It instructs Angular to run change detection for a component subtree <strong>only</strong> when:</p><ul><li>The root component of the subtree receives new inputs as the result of a template binding. Angular compares the current and past value of the input with <code>Object.is</code>.</li><li>Angular handles an event <em>(for example using event binding, output binding, or <code>@HostListener</code> )</em> in the subtree&#39;s root component or any of its children whether they are using OnPush change detection or not.</li><li>A component in the subtree is marked for check, for example with <code>ChangeDetectorRef.markForCheck</code> or by <code>AsyncPipe</code>.</li><li>A signal read in the template of a component in the subtree changes. Angular then refreshes only the components that read the signal.</li></ul><h2 id="common-change-detection-scenarios" tabindex="-1">Common change detection scenarios <a class="header-anchor" href="#common-change-detection-scenarios" aria-label="Permalink to &quot;Common change detection scenarios&quot;">​</a></h2><p>This section examines several common change detection scenarios to illustrate Angular&#39;s behavior.</p><h3 id="an-event-is-handled-by-a-component-with-eager-change-detection" tabindex="-1">An event is handled by a component with <code>Eager</code> change detection <a class="header-anchor" href="#an-event-is-handled-by-a-component-with-eager-change-detection" aria-label="Permalink to &quot;An event is handled by a component with \`Eager\` change detection&quot;">​</a></h3><p>If Angular handles an event within a component with the <code>Eager</code> strategy, the framework executes change detection on the entire component tree. Angular will skip descendant component subtrees with roots using <code>OnPush</code>, which have not received new inputs.</p><p>As an example, if we set the change detection strategy of <code>MainComponent</code> to <code>OnPush</code> and the user interacts with a component outside the subtree with root <code>MainComponent</code>, Angular will check all the pink components from the diagram below (<code>AppComponent</code>, <code>HeaderComponent</code>, <code>SearchComponent</code>, <code>ButtonComponent</code>) unless <code>MainComponent</code> receives new inputs:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>graph TD;</span></span>
<span class="line"><span>    app[AppComponent] --- header[HeaderComponent];</span></span>
<span class="line"><span>    app --- main[&quot;MainComponent (OnPush)&quot;];</span></span>
<span class="line"><span>    header --- search[SearchComponent];</span></span>
<span class="line"><span>    header --- button[ButtonComponent];</span></span>
<span class="line"><span>    main --- login[&quot;LoginComponent (OnPush)&quot;];</span></span>
<span class="line"><span>    main --- details[DetailsComponent];</span></span>
<span class="line"><span>    event&gt;Event] --- search</span></span>
<span class="line"><span></span></span>
<span class="line"><span>class app checkedNode</span></span>
<span class="line"><span>class header checkedNode</span></span>
<span class="line"><span>class button checkedNode</span></span>
<span class="line"><span>class search checkedNode</span></span>
<span class="line"><span>class event eventNode</span></span></code></pre></div><h2 id="an-event-is-handled-by-a-component-with-onpush" tabindex="-1">An event is handled by a component with OnPush <a class="header-anchor" href="#an-event-is-handled-by-a-component-with-onpush" aria-label="Permalink to &quot;An event is handled by a component with OnPush&quot;">​</a></h2><p>If Angular handles an event within a component with OnPush strategy, the framework will execute change detection within the entire component tree. Angular will ignore component subtrees with roots using OnPush, which have not received new inputs and are outside the component which handled the event.</p><p>As an example, if Angular handles an event within <code>MainComponent</code>, the framework will run change detection in the entire component tree. Angular will ignore the subtree with root <code>LoginComponent</code> because it has <code>OnPush</code> and the event happened outside of its scope.</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>graph TD;</span></span>
<span class="line"><span>    app[AppComponent] --- header[HeaderComponent];</span></span>
<span class="line"><span>    app --- main[&quot;MainComponent (OnPush)&quot;];</span></span>
<span class="line"><span>    header --- search[SearchComponent];</span></span>
<span class="line"><span>    header --- button[ButtonComponent];</span></span>
<span class="line"><span>    main --- login[&quot;LoginComponent (OnPush)&quot;];</span></span>
<span class="line"><span>    main --- details[DetailsComponent];</span></span>
<span class="line"><span>    event&gt;Event] --- main</span></span>
<span class="line"><span></span></span>
<span class="line"><span>class app checkedNode</span></span>
<span class="line"><span>class header checkedNode</span></span>
<span class="line"><span>class button checkedNode</span></span>
<span class="line"><span>class search checkedNode</span></span>
<span class="line"><span>class main checkedNode</span></span>
<span class="line"><span>class details checkedNode</span></span>
<span class="line"><span>class event eventNode</span></span></code></pre></div><h2 id="an-event-is-handled-by-a-descendant-of-a-component-with-onpush" tabindex="-1">An event is handled by a descendant of a component with OnPush <a class="header-anchor" href="#an-event-is-handled-by-a-descendant-of-a-component-with-onpush" aria-label="Permalink to &quot;An event is handled by a descendant of a component with OnPush&quot;">​</a></h2><p>If Angular handles an event in a component with OnPush, the framework will execute change detection in the entire component tree, including the component’s ancestors.</p><p>As an example, in the diagram below, Angular handles an event in <code>LoginComponent</code> which uses OnPush. Angular will invoke change detection in the entire component subtree including <code>MainComponent</code> (<code>LoginComponent</code>’s parent), even though <code>MainComponent</code> has <code>OnPush</code> as well. Angular checks <code>MainComponent</code> as well because <code>LoginComponent</code> is part of its view.</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>graph TD;</span></span>
<span class="line"><span>    app[AppComponent] --- header[HeaderComponent];</span></span>
<span class="line"><span>    app --- main[&quot;MainComponent (OnPush)&quot;];</span></span>
<span class="line"><span>    header --- search[SearchComponent];</span></span>
<span class="line"><span>    header --- button[ButtonComponent];</span></span>
<span class="line"><span>    main --- login[&quot;LoginComponent (OnPush)&quot;];</span></span>
<span class="line"><span>    main --- details[DetailsComponent];</span></span>
<span class="line"><span>    event&gt;Event] --- login</span></span>
<span class="line"><span></span></span>
<span class="line"><span>class app checkedNode</span></span>
<span class="line"><span>class header checkedNode</span></span>
<span class="line"><span>class button checkedNode</span></span>
<span class="line"><span>class search checkedNode</span></span>
<span class="line"><span>class login checkedNode</span></span>
<span class="line"><span>class main checkedNode</span></span>
<span class="line"><span>class details checkedNode</span></span>
<span class="line"><span>class event eventNode</span></span></code></pre></div><h2 id="new-inputs-to-component-with-onpush" tabindex="-1">New inputs to component with OnPush <a class="header-anchor" href="#new-inputs-to-component-with-onpush" aria-label="Permalink to &quot;New inputs to component with OnPush&quot;">​</a></h2><p>Angular will run change detection within a child component with <code>OnPush</code> when setting an input property as result of a template binding.</p><p>For example, in the diagram below, <code>AppComponent</code> passes a new input to <code>MainComponent</code>, which has <code>OnPush</code>. Angular will run change detection in <code>MainComponent</code> but will not run change detection in <code>LoginComponent</code>, which also has <code>OnPush</code>, unless it receives new inputs as well.</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>graph TD;</span></span>
<span class="line"><span>    app[AppComponent] --- header[HeaderComponent];</span></span>
<span class="line"><span>    app --- main[&quot;MainComponent (OnPush)&quot;];</span></span>
<span class="line"><span>    header --- search[SearchComponent];</span></span>
<span class="line"><span>    header --- button[ButtonComponent];</span></span>
<span class="line"><span>    main --- login[&quot;LoginComponent (OnPush)&quot;];</span></span>
<span class="line"><span>    main --- details[DetailsComponent];</span></span>
<span class="line"><span>    event&gt;Parent passes new input to MainComponent]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>class app checkedNode</span></span>
<span class="line"><span>class header checkedNode</span></span>
<span class="line"><span>class button checkedNode</span></span>
<span class="line"><span>class search checkedNode</span></span>
<span class="line"><span>class main checkedNode</span></span>
<span class="line"><span>class details checkedNode</span></span>
<span class="line"><span>class event eventNode</span></span></code></pre></div><h2 id="edge-cases" tabindex="-1">Edge cases <a class="header-anchor" href="#edge-cases" aria-label="Permalink to &quot;Edge cases&quot;">​</a></h2><ul><li><strong>Modifying input properties in TypeScript code</strong>. When you use an API like <code>@ViewChild</code> or <code>@ContentChild</code> to get a reference to a component in TypeScript and manually modify an <code>@Input</code> property, Angular will not automatically run change detection for OnPush components. If you need Angular to run change detection, you can inject <code>ChangeDetectorRef</code> in your component and call <code>changeDetectorRef.markForCheck()</code> to tell Angular to schedule a change detection.</li><li><strong>Modifying object references</strong>. In case an input receives a mutable object as value and you modify the object but preserve the reference, Angular will not invoke change detection. That’s the expected behavior because the previous and the current value of the input point to the same reference.</li></ul>`,26)]))}const m=e(o,[["render",p]]);export{u as __pageData,m as default};
